import type { Metadata } from "next";
import { siteConfig, type Locale } from "@/site.config";

/** Size of the social image generated by `app/[locale]/opengraph-image.tsx`. */
export const OG_IMAGE_SIZE = { width: 1200, height: 630 } as const;

type OpenGraphImages = NonNullable<NonNullable<Metadata["openGraph"]>["images"]>;

/**
 * The shared social image for `locale`, for a page's `openGraph.images`.
 *
 * Every page that sets its own `openGraph` must include it: Next.js merges metadata
 * shallowly, so a page's `openGraph` replaces the layout's whole object, image included.
 * The URL is relative and resolved against `metadataBase`; `/en/...` is accepted by
 * `proxy.ts`, which rewrites it onto the same `[locale]` tree.
 */
export function ogImages(locale: Locale, alt: string): OpenGraphImages {
  return [{ url: `/${locale}/opengraph-image`, ...OG_IMAGE_SIZE, type: "image/png", alt }];
}

/** The large-image card, so links shared on X show the image rather than a thumbnail. */
export function twitterCard(locale: Locale, alt: string): Metadata["twitter"] {
  return { card: "summary_large_image", images: [{ url: `/${locale}/opengraph-image`, alt }] };
}

/** `og:locale` for a site locale. */
export function ogLocale(locale: Locale): string {
  return locale === "en" ? "en_US" : "es_ES";
}

/** Public path of a page: English at the root, Spanish under `/es` (see `proxy.ts`). */
export function localePath(locale: Locale, path = ""): string {
  const prefix = locale === "en" ? "" : "/es";
  return `${prefix}${path}` || "/";
}

/** Absolute URL of a page, for `og:url`. */
export function absoluteUrl(locale: Locale, path = ""): string {
  const local = localePath(locale, path);
  return local === "/" ? siteConfig.url : `${siteConfig.url}${local}`;
}
